#!/usr/bin/env node
// Copies the general-purpose Tabler Icons used by the ribbon (src/ui/icons/README.md) from the SVG
// files of the @tabler/icons package (devDependency, exact version in package.json) into
// src/ui/icons/tabler.ts. Run after changing TABLER_NAMES or the package version:
//   node scripts/gen_tabler_icons.mjs
// The Jest test src/ui/icons/__tests__/icons.test.ts checks that the generated file matches the
// installed package.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const pkgDir = path.join(root, 'node_modules', '@tabler', 'icons');

/** Tabler icon names copied into the bundle, in the order of the generated file. */
export const TABLER_NAMES = [
  'file-plus',
  'folder-open',
  'device-floppy',
  'arrow-back-up',
  'arrow-forward-up',
  'file-export',
  'file-import',
  'printer',
  'ruler-measure',
  'search',
  'settings',
  'pointer',
  'zoom-scan',
  'trash',
  'chevron-up',
  'chevron-down',
  'x',
  'refresh',
  'eye',
  'list-details',
];

/** Inner markup of one outline icon: its drawing elements without the invisible 24×24 frame. */
export function tablerBody(svgText) {
  const inner = svgText.replace(/^[\s\S]*?<svg[^>]*>/, '').replace(/<\/svg>\s*$/, '');
  return inner
    .split('\n')
    .map((l) => l.trim())
    .filter((l) => l && !l.includes('stroke="none"'))
    .map((l) => l.replace(/\s*\/>$/, '/>'))
    .join('');
}

/** Text of src/ui/icons/tabler.ts for the installed package. */
export function generate() {
  const pkg = JSON.parse(fs.readFileSync(path.join(pkgDir, 'package.json'), 'utf8'));
  const license = fs.readFileSync(path.join(pkgDir, 'LICENSE'), 'utf8').trim();
  const copyright = license.split('\n').find((l) => l.startsWith('Copyright'));
  const lines = [
    '// Generated by scripts/gen_tabler_icons.mjs from the SVG files of',
    `// @tabler/icons ${pkg.version} (${pkg.license} License, https://tabler.io/icons). Do not edit by hand.`,
    `// ${copyright}`,
    '// Licensed under the MIT License: the full text is in src/ui/icons/README.md and in',
    '// node_modules/@tabler/icons/LICENSE.',
    '',
    `export const TABLER_VERSION = '${pkg.version}';`,
    '',
    '/** Tabler outline icons: name → inner SVG markup of a 24×24, stroke 2, round-cap icon. */',
    'export const TABLER_ICONS: Record<string, string> = {',
  ];
  for (const name of TABLER_NAMES) {
    const svg = fs.readFileSync(path.join(pkgDir, 'icons', 'outline', `${name}.svg`), 'utf8');
    lines.push(`  '${name}': '${tablerBody(svg)}',`);
  }
  lines.push('};', '');
  return lines.join('\n');
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  fs.writeFileSync(path.join(root, 'src', 'ui', 'icons', 'tabler.ts'), generate());
  console.log(`src/ui/icons/tabler.ts: ${TABLER_NAMES.length} icons`);
}
